interface Box<T> {
    T get();
}

class StringBox implements Box<String> {
    public String get() {
        return "value";
    }
}

# Після erasure Box.get має Object get().
# Але StringBox написав String get().
# javac додає bridge:
# public Object get() { return get(); } // ідея, з cast/dispatch деталями

